private final ReentrantLock lock = new ReentrantLock();
private final Condition notEmpty = lock.newCondition();
private final Condition notFull  = lock.newCondition();

public void put(T item) throws InterruptedException {
    lock.lock();
    try {
        while (isFull()) notFull.await();
        enqueue(item);
        notEmpty.signal();      // chỉ đánh thức consumer, không đánh thức producer
    } finally {
        lock.unlock();          // BẮT BUỘC trong finally
    }
}

// Double-checked locking — volatile là BẮT BUỘC
private volatile Config instance;

public Config get() {
    Config local = instance;
    if (local == null) {
        synchronized (this) {
            local = instance;
            if (local == null) instance = local = new Config();
        }
    }
    return local;
}

